INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss das Design immer direkt mit der Softwarestruktur verknüpft sein?', 2, '[{"text": "Nein", "correct": true, "because": "Kann zunächst unabhängig entwickelt werden"}, {"text": "Ja", "correct": false, "because": "Abstimmung kommt oft später"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element hilft mir, Design und Softwarestruktur abzustimmen?', 3, '[{"text": "Komponenten-Modularität", "correct": true, "because": "Design spiegelt Code-Module wider"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch, nicht strukturell"}, {"text": "Schriftgröße", "correct": false, "because": "Kein Bezug zur Architektur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Verbindung von Design und Software?', 5, '[{"text": "Datenfluss", "correct": true, "because": "Beeinflusst UI und Backend"}, {"text": "Komponentenwiederverwendung", "correct": true, "because": "Konsistenz in Design und Code"}, {"text": "Farbanpassung", "correct": false, "because": "Ästhetisch, nicht strukturell"}, {"text": "Typografie", "correct": false, "because": "Kein direkter Architekturbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Design und Softwarestruktur sollten synchron sein. b) Sie können völlig getrennt bleiben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Trennung erschwert Umsetzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist unpraktisch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abstimmung von Design und Softwarestruktur?', 4, '[{"text": "Datenmodelle", "correct": false, "because": "Wichtig für Konsistenz"}, {"text": "Interaktionsfluss", "correct": false, "because": "Verbindet UI mit Logik"}, {"text": "Designer-Präferenzen", "correct": true, "because": "Technische Umsetzung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Softwarestruktur das Design komplett bestimmt?', 2, '[{"text": "Nein", "correct": true, "because": "Design kann Architektur beeinflussen"}, {"text": "Ja", "correct": false, "because": "Beidseitige Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft mir, Design mit Code-Architektur zu verbinden?', 3, '[{"text": "Modularität", "correct": true, "because": "Erleichtert Zuordnung von UI zu Code"}, {"text": "Farbcodierung", "correct": false, "because": "Nur visuell relevant"}, {"text": "Schriftwahl", "correct": false, "because": "Kein Bezug zur Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutze ich, um Design und Softwarestruktur abzustimmen?', 5, '[{"text": "Komponenten-Mapping", "correct": true, "because": "Verknüpft UI mit Code-Bausteinen"}, {"text": "Datenflussdiagramme", "correct": true, "because": "Zeigt Interaktionen"}, {"text": "Mockup-Erstellung", "correct": false, "because": "Nur visuell"}, {"text": "Typografie-Guidelines", "correct": false, "because": "Ästhetisch, nicht strukturell"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Design und Architektur beeinflussen sich gegenseitig. b) Design hat keinen Einfluss auf Code. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Design kann Struktur formen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich Design und Softwarestruktur verbinde?', 4, '[{"text": "UI-Komponenten", "correct": false, "because": "Wichtig für Zuordnung"}, {"text": "Datenfluss", "correct": false, "because": "Verknüpft Frontend und Backend"}, {"text": "Endgültige Farben", "correct": true, "because": "Ästhetik ist sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ich die Softwarestruktur vor dem Design kennen?', 2, '[{"text": "Nein", "correct": true, "because": "Design kann iterativ angepasst werden"}, {"text": "Ja", "correct": false, "because": "Kann parallel entwickelt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze fördern die Abstimmung von Design und Architektur?', 4, '[{"text": "MVC-Pattern", "correct": true, "because": "Trennt UI und Logik klar"}, {"text": "Komponentenbasierte Entwicklung", "correct": true, "because": "Spiegelt Design wider"}, {"text": "Zufällige Farbwahl", "correct": false, "because": "Kein Bezug zur Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Softwarestruktur das Design einschränkt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Technische Limits können Design beeinflussen"}, {"text": "Nein", "correct": false, "because": "Es gibt oft Spielraum"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Design mit Softwarestruktur abstimme?', 3, '[{"text": "Konsistenz der Komponenten", "correct": true, "because": "Erleichtert Entwicklung"}, {"text": "Visuelle Details", "correct": false, "because": "Später relevant"}, {"text": "Schriftarten", "correct": false, "because": "Ästhetisch, nicht strukturell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Design muss an die Architektur angepasst werden. b) Architektur ist immer unabhängig vom Design.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Architektur kann Design beeinflussen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren verbinden Design und Softwarestruktur effektiv?', 5, '[{"text": "Datenmodelle", "correct": true, "because": "UI spiegelt Daten wider"}, {"text": "Interaktionsmuster", "correct": true, "because": "Verknüpft Nutzung mit Logik"}, {"text": "Farbtöne", "correct": false, "because": "Nur visuell"}, {"text": "Animationen", "correct": false, "because": "Ästhetisch, nicht strukturell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verbindung von Design und Architektur?', 3, '[{"text": "Technische Machbarkeit", "correct": false, "because": "Muss berücksichtigt werden"}, {"text": "Benutzerinteraktion", "correct": false, "because": "Verknüpft beide"}, {"text": "Persönliche Vorlieben", "correct": true, "because": "Technik steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der Abstimmung? Ist sie nur für große Projekte nötig?', 3, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Universell sinnvoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Design ohne Architektur entworfen werden kann?', 2, '[{"text": "Ja", "correct": true, "because": "Erste Entwürfe können unabhängig sein"}, {"text": "Nein", "correct": false, "because": "Spätere Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Muster hilft mir, Design und Softwarestruktur zu synchronisieren?', 4, '[{"text": "MVVM", "correct": true, "because": "Bindet UI an Datenmodelle"}, {"text": "Statisches Mockup", "correct": false, "because": "Keine Architekturverbindung"}, {"text": "Typografische Regeln", "correct": false, "because": "Nur visuell"}]');
